                if( size > 0 &&
                        data ) {
                        ed->data = malloc( size );
                        memcpy( ed->data, data, size );
                        ed->size = size;
                }
        }

        return( 0 );
}

/* Skip any spaces.
 */
static const char *
skip_space( const char *p )
{
        while( p && *p == ' ' )
                p += 1;

        return( p );
}

/* Skip to the end of this non-space sequence.
 */
static const char *
skip_nonspace( const char *p )
{
        while( p && *p && *p != ' ' )
                p += 1;

        return( p );
}

